sketch.css:
.rf{box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;gap:10px;padding:12px 14px;background:var(--window);color:var(--text);font:13px/1.4 "Segoe UI",system-ui,sans-serif;overflow:hidden}
.rf *{box-sizing:border-box}
.kpis{display:flex;gap:18px;margin-bottom:8px}
.kpi .kl{color:var(--muted);font-size:11.5px;font-weight:500}
.kpi .kv{font-size:20px;font-weight:700;letter-spacing:-.01em;line-height:1.2}
.kpi.alert .kv{color:var(--red)}
.statusbar{display:flex;height:10px;border-radius:5px;overflow:hidden;gap:2px;background:var(--background)}
.seg{height:100%;cursor:pointer;transition:opacity .15s}
.statusbar.filtered .seg{opacity:.3}
.statusbar.filtered .seg.selected{opacity:1}
.statuslegend{display:flex;flex-wrap:wrap;gap:4px 12px;margin-top:6px}
.lg{display:flex;align-items:center;gap:5px;font-size:11.5px;color:var(--muted);cursor:pointer;padding:1px 6px;border-radius:10px}
.lg:hover{background:var(--hover)}
.lg.selected{background:var(--hover);color:var(--text)}
.lg i{width:8px;height:8px;border-radius:2px;background:var(--c)}
.lg b{color:var(--text);font-weight:600}
.main{flex:1;display:flex;gap:12px;min-height:0}
.listpane{flex:1;display:flex;flex-direction:column;min-width:0;border-top:1px solid var(--border)}
.listhead{display:flex;justify-content:space-between;align-items:center;padding:6px 2px}
.lh-title{font-weight:600}
.groupby{display:flex;gap:2px;background:var(--background);border-radius:8px;padding:2px}
.gb{padding:2px 9px;border-radius:6px;font-size:11.5px;font-weight:500;color:var(--muted);cursor:pointer}
.gb:hover{color:var(--text)}
.gb.selected{background:var(--window);color:var(--accent);box-shadow:0 1px 2px rgba(20,20,50,.1)}
.list{flex:1;overflow:auto}
.group{display:flex;justify-content:space-between;padding:8px 6px 4px;font-size:11.5px;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.03em;border-bottom:1px solid var(--border)}
.group span{text-transform:none;letter-spacing:0;font-weight:500}
.row{display:grid;grid-template-columns:16px 1fr 116px 64px 66px;gap:10px;align-items:center;padding:7px 6px;border-bottom:1px solid var(--border);cursor:pointer;border-radius:6px}
.row:hover{background:var(--hover)}
.row.selected{background:var(--hover);box-shadow:inset 3px 0 0 var(--accent)}
.chev{width:16px;height:16px;color:var(--muted);border-radius:4px;transition:transform .15s}
.chev:hover{background:var(--background);color:var(--accent)}
.row.expanded .chev{transform:rotate(90deg)}
.chev svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.id{display:flex;align-items:center;gap:6px;font-weight:600}
.kind{font-size:10.5px;font-weight:600;padding:0 6px;border-radius:8px;color:var(--muted);background:var(--background)}
.route{color:var(--muted);font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.track{position:relative;height:6px;border-radius:3px;background:var(--background)}
.fill{position:absolute;left:0;top:0;bottom:0;border-radius:3px;background:var(--c)}
.train{position:absolute;top:50%;width:10px;height:10px;margin:-5px 0 0 -5px;border-radius:50%;background:var(--window);border:2px solid var(--c)}
.chip{display:inline-block;font-size:11px;font-weight:600;color:var(--c);margin-top:4px}
.days{font-size:12px;text-align:center}
.days b{font-weight:600}
.days small{display:block;color:var(--muted);font-size:11px}
.days.over b{color:var(--red)}
.right{text-align:right}
.cars{font-weight:600}
.eta{color:var(--muted);font-size:11.5px}
.late{color:var(--red);font-weight:600}
.carlist{display:flex;flex-wrap:wrap;gap:4px;padding:6px 6px 9px 32px;border-bottom:1px solid var(--border);background:color-mix(in srgb,var(--hover) 45%,transparent)}
.car{font:11px/1.6 Consolas,"Cascadia Mono",monospace;padding:0 6px;border-radius:5px;background:var(--window);border:1px solid var(--border)}
.car.more{font-family:inherit;color:var(--muted);border-style:dashed}
.map{width:280px;flex:none;border:1px solid var(--border);border-radius:10px;background:var(--background);position:relative;overflow:hidden}
.map svg{display:block;width:100%;height:100%}
.land{fill:var(--window);stroke:var(--border);stroke-width:1}
.arc{fill:none;stroke:var(--c);stroke-width:1.6;opacity:.45;stroke-dasharray:4 3;cursor:pointer}
.arc.done{stroke-dasharray:none;opacity:.9}
.arc.selected{opacity:1;stroke-width:2.6}
.pin{fill:var(--window);stroke:var(--muted);stroke-width:1.4}
.pin.term{fill:var(--text);stroke:none}
.pos{fill:var(--c);stroke:var(--window);stroke-width:1.6;cursor:pointer}
.pos.selected{stroke:var(--text)}
.place{font-size:9px;fill:var(--muted)}
.maptitle{position:absolute;left:10px;top:8px;font-size:11.5px;font-weight:600;color:var(--muted)}
.empty{color:var(--muted);text-align:center;padding:24px 0}

sketch.js:
function render(root, props, fire) {
  const STATUS = [
    { key: 'loading', text: 'Loading', c: 'var(--amber)' },
    { key: 'transit', text: 'In transit', c: 'var(--accent)' },
    { key: 'destination', text: 'At destination', c: 'var(--green)' },
    { key: 'empty', text: 'Empty return', c: 'var(--sky)' },
    { key: 'badorder', text: 'Bad order', c: 'var(--red)' }
  ];
  const GROUPS = [{ key: 'none', text: 'All' }, { key: 'destination', text: 'Terminal' }, { key: 'origin', text: 'Plant' }];
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const st = k => STATUS.find(s => s.key === k) || STATUS[1];
  const ships = props.shipments || [];
  const filter = props.statusFilter && props.statusFilter !== 'all' ? props.statusFilter : '';
  const groupBy = props.groupBy || 'destination';
  const maxCars = props.carNumbersShown || 12;

  // fleet totals by status: the cars of every shipment
  const counts = {}; let total = 0, late = 0;
  STATUS.forEach(s => counts[s.key] = 0);
  ships.forEach(s => { const n = +s.cars || 0; counts[st(s.status).key] += n; total += n; if ((+s.daysOut || 0) > (+s.expectedDays || 0)) late += n; });

  root.querySelector('.kpis').innerHTML =
    '<div class="kpi"><div class="kl">Fleet</div><div class="kv">' + total.toLocaleString() + '</div></div>' +
    '<div class="kpi"><div class="kl">In transit</div><div class="kv">' + counts.transit.toLocaleString() + '</div></div>' +
    '<div class="kpi' + (late ? ' alert' : '') + '"><div class="kl">Overdue cars</div><div class="kv">' + late + '</div></div>' +
    '<div class="kpi"><div class="kl">Shipments</div><div class="kv">' + ships.length + '</div></div>';

  const bar = root.querySelector('.statusbar');
  bar.classList.toggle('filtered', !!filter);
  bar.innerHTML = STATUS.filter(s => counts[s.key]).map(s => '<span class="seg' + (s.key === filter ? ' selected' : '') + '" data-k="' + s.key + '" title="' + s.text + '" style="flex:' + counts[s.key] + ';background:' + s.c + '"></span>').join('');
  root.querySelector('.statuslegend').innerHTML = STATUS.map(s => '<span class="lg' + (s.key === filter ? ' selected' : '') + '" data-k="' + s.key + '" style="--c:' + s.c + '"><i></i>' + s.text + ' <b>' + counts[s.key] + '</b></span>').join('');
  root.querySelectorAll('.seg,.lg').forEach(el => el.onclick = () => fire('statusFilterChanged', { statusFilter: el.dataset.k === filter ? 'all' : el.dataset.k }));

  // group switch
  const gb = root.querySelector('.groupby');
  gb.innerHTML = GROUPS.map(g => '<span class="gb' + (g.key === groupBy ? ' selected' : '') + '" data-g="' + g.key + '">' + g.text + '</span>').join('');
  gb.querySelectorAll('.gb').forEach(el => el.onclick = () => fire('groupByChanged', { groupBy: el.dataset.g }));

  // shipments of the filtered status, grouped
  const shown = ships.filter(s => !filter || st(s.status).key === filter);
  const list = root.querySelector('.list');
  const rowHtml = s => {
    const S = st(s.status), p = Math.max(0, Math.min(100, +s.progress || 0));
    const out = +s.daysOut || 0, exp = +s.expectedDays || 0, over = out - exp;
    const open = s.id === props.expanded;
    let h = '<div class="row' + (s.id === props.selected ? ' selected' : '') + (open ? ' expanded' : '') + '" data-id="' + esc(s.id) + '" style="--c:' + S.c + '">' +
      '<span class="chev" data-x="' + esc(s.id) + '"><svg viewBox="0 0 24 24"><path d="M9 6l6 6-6 6"/></svg></span>' +
      '<div style="min-width:0"><div class="id">' + esc(s.id) + '<span class="kind">' + (s.unitTrain ? 'Unit train' : 'Manifest') + '</span></div>' +
      '<div class="route">' + esc(s.origin) + ' → ' + esc(s.destination) + '</div></div>' +
      '<div><div class="track"><span class="fill" style="width:' + p + '%"></span><span class="train" style="left:' + p + '%"></span></div><span class="chip">' + S.text + '</span></div>' +
      '<div class="days' + (over > 0 ? ' over' : '') + '"><b>Day ' + out + '</b><small>of ' + exp + '</small></div>' +
      '<div class="right"><div class="cars">' + (+s.cars || 0) + ' cars</div>' +
      (over > 0 ? '<div class="eta late">+' + over + 'd late</div>' : '<div class="eta">ETA ' + esc(s.eta) + '</div>') + '</div></div>';
    if (open) {
      const nums = s.carNumbers || [];
      const rest = Math.max(0, (+s.cars || 0) - Math.min(nums.length, maxCars));
      h += '<div class="carlist">' + nums.slice(0, maxCars).map(n => '<span class="car">' + esc(n) + '</span>').join('') +
        (rest ? '<span class="car more">+' + rest + ' more</span>' : '') + '</div>';
    }
    return h;
  };
  if (!shown.length) list.innerHTML = '<div class="empty">No shipments</div>';
  else if (groupBy === 'none') list.innerHTML = shown.map(rowHtml).join('');
  else {
    const keys = []; const by = {};
    shown.forEach(s => { const k = s[groupBy] || '—'; if (!by[k]) { by[k] = []; keys.push(k); } by[k].push(s); });
    list.innerHTML = keys.map(k => '<div class="group">' + esc(k) + '<span>' + by[k].length + ' shipment' + (by[k].length > 1 ? 's' : '') + ' · ' +
      by[k].reduce((a, s) => a + (+s.cars || 0), 0) + ' cars</span></div>' + by[k].map(rowHtml).join('')).join('');
  }
  list.querySelectorAll('.row').forEach(el => el.onclick = () => fire('shipmentSelected', { id: el.dataset.id, selected: el.dataset.id }));
  list.querySelectorAll('.chev').forEach(el => el.onclick = e => {
    e.stopPropagation();
    const id = el.dataset.x;
    fire('shipmentExpanded', { id: id, expanded: id === props.expanded ? '' : id });
  });

  // route map: the lower 48 in a plain lon/lat projection, an arc per shipment, the train on it
  const map = root.querySelector('.map');
  map.style.display = props.showMap === false ? 'none' : '';
  if (props.showMap === false) return;
  const W = 280, H = 190, L = -125.5, R = -66, T = 50, B = 24;
  const px = lon => (lon - L) / (R - L) * W, py = lat => (T - lat) / (T - B) * H;
  const US = [[-124.7,48.4],[-124.1,46.2],[-124.4,42],[-123.8,39.8],[-122.4,37.2],[-120.6,34.6],[-117.1,32.5],[-114.7,32.7],[-111,31.3],[-108.2,31.3],[-106.5,31.8],[-104.5,29.6],[-103,29],[-101.4,29.8],[-99.5,27.5],[-97.4,25.9],[-97.2,27.7],[-94,29.6],[-90,29.1],[-89.4,30.2],[-85,29.7],[-83,29],[-82.6,27.5],[-81,25.2],[-80.1,26.5],[-80.6,28.5],[-81.4,30.7],[-79,33.5],[-75.5,35.2],[-76,37],[-74,39.5],[-71,41.5],[-70,41.8],[-70.7,43],[-67,44.8],[-67.8,47.1],[-69.2,47.4],[-71.5,45],[-74.9,45],[-76.5,44],[-79.2,43.4],[-82.5,41.7],[-82.7,45],[-84.6,46.5],[-88,48],[-95.2,49],[-123,49]];
  const land = 'M' + US.map(p => px(p[0]).toFixed(1) + ' ' + py(p[1]).toFixed(1)).join(' L') + 'Z';
  const places = {};
  let arcs = '', trains = '';
  ships.filter(s => !filter || st(s.status).key === filter).forEach(s => {
    if (s.originLon == null || s.destLon == null) return;
    const S = st(s.status), sel = s.id === props.selected;
    const x1 = px(s.originLon), y1 = py(s.originLat), x2 = px(s.destLon), y2 = py(s.destLat);
    const mx = (x1 + x2) / 2, my = (y1 + y2) / 2 - Math.hypot(x2 - x1, y2 - y1) * .18;
    const t = Math.max(0, Math.min(100, +s.progress || 0)) / 100;
    const tx = (1 - t) * (1 - t) * x1 + 2 * (1 - t) * t * mx + t * t * x2, ty = (1 - t) * (1 - t) * y1 + 2 * (1 - t) * t * my + t * t * y2;
    arcs += '<path class="arc' + (t >= 1 ? ' done' : '') + (sel ? ' selected' : '') + '" data-id="' + esc(s.id) + '" style="--c:' + S.c + '" d="M' + x1.toFixed(1) + ' ' + y1.toFixed(1) + ' Q' + mx.toFixed(1) + ' ' + my.toFixed(1) + ' ' + x2.toFixed(1) + ' ' + y2.toFixed(1) + '"/>';
    trains += '<circle class="pos' + (sel ? ' selected' : '') + '" data-id="' + esc(s.id) + '" style="--c:' + S.c + '" cx="' + tx.toFixed(1) + '" cy="' + ty.toFixed(1) + '" r="' + (sel ? 5 : 4) + '"><title>' + esc(s.id) + '</title></circle>';
    places[s.origin] = places[s.origin] || { x: x1, y: y1, term: false };
    places[s.destination] = { x: x2, y: y2, term: true };
  });
  const pins = Object.keys(places).map(n => { const p = places[n]; return '<circle class="pin' + (p.term ? ' term' : '') + '" cx="' + p.x.toFixed(1) + '" cy="' + p.y.toFixed(1) + '" r="2.6"><title>' + esc(n) + '</title></circle>' +
    (p.term ? '<text class="place" x="' + (p.x + 4).toFixed(1) + '" y="' + (p.y + 3).toFixed(1) + '">' + esc(n.split(',')[0]) + '</text>' : ''); }).join('');
  map.innerHTML = '<span class="maptitle">Routes</span><svg viewBox="-6 -24 ' + (W + 12) + ' ' + (H + 34) + '" preserveAspectRatio="xMidYMid meet"><path class="land" d="' + land + '"/>' + arcs + pins + trains + '</svg>';
  map.querySelectorAll('.arc,.pos').forEach(el => el.onclick = () => fire('shipmentSelected', { id: el.dataset.id, selected: el.dataset.id }));
}
